using System.Net;using System.Net.Http.Headers;using System.Text;using System.Text.Json;
namespace RaceDay.Mvc.Services;
public class RaceDayApiClient(HttpClient http,IHttpContextAccessor accessor){
 HttpClient Client=>http; ISession? Session=>accessor.HttpContext?.Session;
 void AddCookie(HttpRequestMessage req){var c=Session?.GetString("ApiCookie");if(!string.IsNullOrWhiteSpace(c))req.Headers.TryAddWithoutValidation("Cookie",c);}
 async Task<HttpResponseMessage> Send(HttpMethod method,string path,object? body=null){var req=new HttpRequestMessage(method,path);AddCookie(req);if(body!=null)req.Content=new StringContent(JsonSerializer.Serialize(body),Encoding.UTF8,"application/json");return await Client.SendAsync(req);}
 public async Task<(bool Ok,string Message)> Login(string email,string password){var req=new HttpRequestMessage(HttpMethod.Post,"api/auth/login"){Content=new StringContent(JsonSerializer.Serialize(new{email,password}),Encoding.UTF8,"application/json")};var res=await Client.SendAsync(req);if(!res.IsSuccessStatusCode)return(false,await Error(res));if(res.Headers.TryGetValues("Set-Cookie",out var cookies)){var cookie=cookies.FirstOrDefault(x=>x.StartsWith(".RaceDay.Auth="));if(cookie!=null)Session!.SetString("ApiCookie",cookie.Split(';')[0]);}using var doc=JsonDocument.Parse(await res.Content.ReadAsStringAsync());var u=doc.RootElement;Session!.SetString("Role",u.GetProperty("role").GetString()??"");Session.SetString("FirstName",u.GetProperty("firstName").GetString()??"");Session.SetInt32("UserId",u.GetProperty("userId").GetInt32());Session.SetString("Email",email);return(true,"Welcome back!");}
 public async Task<(bool Ok,string Message)> Register(object data){var r=await Send(HttpMethod.Post,"api/auth/register",data);return(r.IsSuccessStatusCode, r.IsSuccessStatusCode?"Account created. You can now sign in.":await Error(r));}
 public async Task<JsonElement> Get(string path){var r=await Send(HttpMethod.Get,path);var s=await r.Content.ReadAsStringAsync();if(!r.IsSuccessStatusCode)throw new ApiException(await Error(r),(int)r.StatusCode);return JsonDocument.Parse(s).RootElement.Clone();}
 public async Task<(bool Ok,string Message)> Post(string path,object data){var r=await Send(HttpMethod.Post,path,data);return(r.IsSuccessStatusCode,r.IsSuccessStatusCode?"Saved successfully.":await Error(r));}
 public async Task<(bool Ok,string Message)> Put(string path,object data){var r=await Send(HttpMethod.Put,path,data);return(r.IsSuccessStatusCode,r.IsSuccessStatusCode?"Changes saved.":await Error(r));}
 public async Task<(bool Ok,string Message)> Delete(string path){var r=await Send(HttpMethod.Delete,path);return(r.IsSuccessStatusCode,r.IsSuccessStatusCode?"Deleted.":await Error(r));}
 public async Task Logout(){await Send(HttpMethod.Post,"api/auth/logout");Session?.Clear();}
 public async Task<(bool Ok,string Message)> Upload(string path,IFormFile file){using var content=new MultipartFormDataContent();await using var stream=file.OpenReadStream();var part=new StreamContent(stream);part.Headers.ContentType=new MediaTypeHeaderValue(file.ContentType);content.Add(part,"file",file.FileName);var req=new HttpRequestMessage(HttpMethod.Post,path){Content=content};AddCookie(req);var r=await Client.SendAsync(req);return(r.IsSuccessStatusCode,r.IsSuccessStatusCode?"Image uploaded.":await Error(r));}
 static async Task<string> Error(HttpResponseMessage r){var s=await r.Content.ReadAsStringAsync();try{using var d=JsonDocument.Parse(s);if(d.RootElement.TryGetProperty("message",out var m))return m.GetString()??"The API request failed.";}catch{}return r.StatusCode==HttpStatusCode.Unauthorized?"Please sign in to continue.":"The request could not be completed. Check the information and try again.";}
}
public class ApiException(string message,int status):Exception(message){public int StatusCode{get;}=status;}